from collections import deque

def oranges_rotting(grid):
    # Slower teaching model: rescan layers with a queue copy each minute
    grid = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0]) if grid else 0
    queue = deque((r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 2)
    minutes = 0
    while queue:
        nxt = deque()
        for r, c in queue:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                    grid[nr][nc] = 2
                    nxt.append((nr, nc))
        if not nxt:
            break
        queue = nxt
        minutes += 1
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                return -1
    return minutes

reference_solution:
from collections import deque

def oranges_rotting(grid):
    grid = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0]) if grid else 0
    queue = deque()
    visited = set()
    fresh = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                queue.append((r, c, 0))
                visited.add((r, c))
            elif grid[r][c] == 1:
                fresh += 1
    minutes = 0
    while queue:
        r, c, t = queue.popleft()
        minutes = max(minutes, t)
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == 1:
                visited.add((nr, nc))
                grid[nr][nc] = 2
                fresh -= 1
                queue.append((nr, nc, t + 1))
    return -1 if fresh else minutes
